// Auto-generated JSON schema types for Griffe API data
// Mirrors the shape produced by scripts/build-api-data.py

export interface DocstringParameter {
  name: string;
  annotation: string | null;
  description: string;
  default: string | null;
}

export interface DocstringReturn {
  annotation: string | null;
  description: string;
}

export interface DocstringRaise {
  annotation: string | null;
  description: string;
}

export interface DocstringAttribute {
  name: string;
  annotation: string | null;
  description: string;
}

export interface DocstringParsed {
  summary: string | null;
  extended: string | null;
  parameters: DocstringParameter[];
  returns: DocstringReturn | null;
  raises: DocstringRaise[];
  examples: string[];
  notes: string[];
  attributes: DocstringAttribute[];
  warns: DocstringRaise[];
  /** ``See Also`` entries parsed out of the docstring's admonition so
   *  the renderer can linkify each name to its docs page rather than
   *  surface raw ``name : description`` prose.  Optional — older
   *  cached JSONs may omit the field. */
  see_also?: SeeAlsoItem[];
}

export interface SeeAlsoItem {
  /** Symbol name as written in the docstring (``"lucid.nn.Linear"`` or
   *  ``"fused_linear_relu"``).  The renderer resolves this to a docs
   *  URL by suffix-matching against the emitted slug set. */
  name: string;
  description: string;
}

// ---------------------------------------------------------------------------
// Labels / decorator kinds
// ---------------------------------------------------------------------------

export type ApiLabel =
  | "property"
  | "staticmethod"
  | "classmethod"
  | "abstractmethod"
  | "writable"
  // A documented plain attribute (``self.merged = False`` with a ``#:``
  // comment, a class-level constant) listed beside the properties.
  | "attribute"
  // C++-specific method kinds (build-cpp-data.py::_cpp_labels).  These
  // co-exist with the Python kinds because the same ``labels: ApiLabel[]``
  // field is shared across both pipelines; downstream renderers pick the
  // first they recognise.
  | "cpp-ctor"
  | "cpp-dtor"
  | "cpp-operator"
  | "cpp-virtual"
  | "cpp-pure-virtual"
  | "cpp-static"
  | "cpp-const"
  | "cpp-template";

// ---------------------------------------------------------------------------
// API members
// ---------------------------------------------------------------------------

/** One node of the expandable layer-summary tree.  Mirrors the shape
 *  emitted by ``lucid/models/_summary.py::compute_model_summary``.
 *  Consecutive structurally-identical siblings collapse into a single
 *  node with ``repeat`` set. */
export interface LayerSummaryNode {
  name: string;
  type: string;
  params: number;
  own_params: number;
  children: LayerSummaryNode[];
  /** Set when this node represents N consecutive identical siblings —
   *  rendered as ``Type × N`` in the docs tree. */
  repeat?: number;
}

export interface ApiFunction extends DocstringParsed {
  name: string;
  path: string;
  kind: "function";
  labels: ApiLabel[];
  signature: string | null;
  source: string | null;
  subcategory?: string | null;
  /** Paper-cited trainable parameter count, extracted from the
   *  ``params=...`` argument of the factory's ``@register_model``
   *  decorator (model factories only).  Absent when the registration
   *  doesn't declare it. */
  param_count?: number;
  /** Expandable layer-summary tree generated by
   *  ``tools/build_model_summaries.py``.  Absent for non-factory
   *  functions, opt-out factories, and any factory that failed to
   *  instantiate at build time. */
  model_summary?: LayerSummaryNode;
}

export interface ApiMethod extends DocstringParsed {
  name: string;
  path: string;
  kind: "function";
  labels: ApiLabel[];
  signature: string | null;
  source: string | null;
  /** Name of the private base class that defines this member, when the class
   *  inherits it from one (``_BaseTuner``): that base has no page, so the
   *  members it contributes are listed on the public class and say so. */
  inherited_from?: string;
}

export type ApiClassKind = "regular" | "abstract" | "dataclass" | "protocol";

export interface ApiClass extends DocstringParsed {
  name: string;
  path: string;
  kind: "class";
  class_kind: ApiClassKind;
  bases: string[];
  labels: ApiLabel[];
  signature: string | null;
  source: string | null;
  subcategory?: string | null;
  methods: ApiMethod[];
}

export type ApiMember = ApiFunction | ApiClass;

// ---------------------------------------------------------------------------
// Module / top-level data files
// ---------------------------------------------------------------------------

export interface FamilyGroup {
  slug: string;
  label: string;
  icon?: string;
}

export interface ApiModule extends DocstringParsed {
  slug: string;
  name: string;
  path: string;
  kind: "module";
  source: string | null;
  members: ApiMember[];
  family_groups?: FamilyGroup[];
  /** Paper-style family display name (``"ResNet"``, ``"ConvNeXt"``,
   *  ``"BERT"``), extracted from the Config class's ``@model_family_meta``
   *  decorator.  Absent → docs renderer falls back to capitalised dirname. */
  canonical_name?: string;
  /** MLA-formatted citation of the family's defining paper, extracted
   *  from ``@model_family_meta(citation=...)``. */
  citation?: string;
  /** rST-formatted theoretical description (multi-paragraph, math OK),
   *  extracted from ``@model_family_meta(theory=...)``.  Rendered through
   *  the same MathText pipeline as docstring extended-description
   *  sections on family-root index pages. */
  theory?: string;
  /** The tasks this family registers — one or more of the eight tags in
   *  ``lucid/models/_tasks.py`` (``"image-classification"``,
   *  ``"language-modeling"``, …).  Read at build time from each
   *  factory's ``@register_model(task=...)``, not re-derived from class
   *  names, so the pills always say what the framework says.  Rendered
   *  as coloured pill badges on the family card. */
  tasks?: string[];
}

/** Special kind for lucid.tensor — a single class exposed as a module */
export interface ApiClassModule extends DocstringParsed {
  slug: string;
  name: string;
  path: string;
  kind: "class-module";
  class_kind: ApiClassKind;
  bases: string[];
  labels: ApiLabel[];
  signature: string | null;
  source: string | null;
  subcategory?: string | null;
  methods: ApiMethod[];
}

export type ApiData = ApiModule | ApiClassModule;

// ---------------------------------------------------------------------------
// Helper type guards
// ---------------------------------------------------------------------------

export function isApiModule(data: ApiData): data is ApiModule {
  return data.kind === "module";
}

export function isApiClassModule(data: ApiData): data is ApiClassModule {
  return data.kind === "class-module";
}

export function isApiClass(member: ApiMember): member is ApiClass {
  return member.kind === "class";
}

export function isApiFunction(member: ApiMember): member is ApiFunction {
  return member.kind === "function";
}

// ---------------------------------------------------------------------------
// Sidebar / navigation
// ---------------------------------------------------------------------------

export interface ModuleEntry {
  slug: string;
  name: string;
  memberCount: number;
  summary: string | null;
}

